// ReqGen 6.0.0: builds the Supabase Edge Functions from the website's own server code, so the
// app (and later the website) use one copy of the logic. Run: node scripts/build-edge.mjs
// Output: supabase/functions/_shared/** (generated, do not edit) plus the hand-written index files.
import { mkdirSync, readFileSync, writeFileSync, rmSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const out = path.join(root, "supabase/functions/_shared/gen");
rmSync(out, { recursive: true, force: true });

// website file -> generated file
const FILES = {
  "lib/sendchamp.ts": "sendchamp.ts",
  "lib/otpHash.ts": "otpHash.ts",
  "lib/server/staffAuth.ts": "staffAuth.ts",
  "lib/server/codeService.ts": "codeService.ts",
  "lib/server/cors.ts": "cors.ts",
  "app/api/notifications/alert/route.ts": "notify_alert.ts",
  "app/api/notifications/sms/request-event/route.ts": "notify_event.ts",
  "app/api/notifications/sms/request-approval/route.ts": "notify_approval.ts",
  "app/api/otp/send/route.ts": "code_send.ts",
  "app/api/otp/verify/route.ts": "code_verify.ts",
  // 6.1.0: reqgen-office (staff accounts, reminders, backups, the financial reset)
  "lib/server/adminAuth.ts": "adminAuth.ts",
  "lib/server/mfaWindow.ts": "mfaWindow.ts",
  "lib/server/superAdmin.ts": "superAdmin.ts",
  "lib/server/backupStore.ts": "backupStore.ts",
  "lib/server/backupBuild.ts": "backupBuild.ts",
  "lib/server/backupCatalog.ts": "backupCatalog.ts",
  "lib/csv.ts": "csv.ts",
  "lib/financialYear.ts": "financialYear.ts",
  "app/api/admin/users/route.ts": "office_admin_users.ts",
  "app/api/admin/users/[id]/route.ts": "office_admin_user.ts",
  "app/api/admin/handover/route.ts": "office_handover.ts",
  "app/api/pv/remind/route.ts": "office_pv_remind.ts",
  "app/api/registry/remind/route.ts": "office_registry_remind.ts",
  "app/api/finance/reset/route.ts": "office_finance_reset.ts",
  "app/api/backup/snapshot/route.ts": "office_backup_snapshot.ts",
  "app/api/backup/export/route.ts": "office_backup_export.ts",
  "app/api/backup/files/route.ts": "office_backup_files.ts",
  "app/api/backup/restore/route.ts": "office_backup_restore.ts",
  "app/api/cron/backup-handover/route.ts": "office_backup_handover.ts",
};
const byWebsitePath = Object.fromEntries(Object.entries(FILES).map(([from, to]) => [from.replace(/\.ts$/, ""), to]));

function convert(src) {
  let s = src;
  s = s.replace(/^import "server-only";\n/m, "");
  s = s.replace(/from "next\/server";/g, 'from "../next_shim.ts";');
  s = s.replace(/from "@supabase\/supabase-js";/g, 'from "npm:@supabase/supabase-js@2.97.0";');
  s = s.replace(/import crypto from "crypto";/g, 'import crypto from "node:crypto";');
  s = s.replace(/from "fflate";/g, 'from "npm:fflate@0.8.2";');
  s = s.replace(/from "@\/([^"]+)";/g, (m, p) => {
    const hit = byWebsitePath[p];
    if (!hit) throw new Error(`Not in the edge list: @/${p}`);
    return `from "./${hit}";`;
  });
  s = s.replace(/^export const (runtime|dynamic) = [^\n]+\n/gm, "");
  return `// GENERATED by scripts/build-edge.mjs from the ReqGen website. Do not edit.\nimport "../env.ts";\n${s}`;
}

mkdirSync(out, { recursive: true });
for (const [from, to] of Object.entries(FILES)) {
  writeFileSync(path.join(out, to), convert(readFileSync(path.join(root, from), "utf8")));
}
console.log("edge functions: generated", Object.keys(FILES).length, "files");
